INSERT INTO characters (slug,name,team,creator,owner_id,tags,appears_in,data,url_slug,status,updated_at,created_at) VALUES
('revenant-scp-fragmented-veil','Revenant','townsfolk','legitch',NULL,'','SCP Fragmented Veil','{"slug":"revenant-scp-fragmented-veil","name":"Revenant","team":"townsfolk","ability":"If you die at night, learn your alive resident neighbour''s characters.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-2718 is the unspeakable and chilling truth about death - there is no afterlife, nor respite from the pain. Only the constant role of witness to your own torment.","summaryBullets":["When the Revenant dies at night, they are immediately woken on that night, and they learn their living neighbour''s characters immediately.","The Revenant skips over learning dead neighbours, and avoids redundantly learning a Traveller''s character."],"howToRun":["If the Revenant died tonight, wake them. Show the character tokens of their closest living non-Traveller players in that direction."],"quote":"''We must declare human death a Keter SCP,'' she demanded, ''and contain it at any cost.''","iconBy":"le_nuberto","jinxes":[{"name":"Leviathan","align":"evil","text":"Each night*, the Leviathan chooses an alive player (different to previous nights): a chosen Revenant uses their ability but does not die","id":"leviathan"},{"name":"Riot","align":"evil","text":"Each night*, Riot chooses an alive good player (different to previous nights): a chosen Revenant uses their ability but does not die.","id":"riot"},{"name":"Matsuraid","align":"evil","text":"If the Revenant is nominated by an evil player and the Matsuraid is in play, they use their ability.","id":"matsuraid_hblreleased"},{"name":"Au’Wre","align":"evil","text":"If Au’Wre guesses the Revenant, they use their ability.","id":"auwre_the_bootleggers_anthology"},{"name":"Ketos","align":"evil","text":"The 1st time Ketos guesses the the Revenant’s character, the Revenant uses their ability.","id":"ketos_the_bootleggers_anthology"},{"name":"Switchblame","align":"evil","text":"If Switchblame is in play & the Revenant dies by execution, they wake that night to use their ability. They are drunk if their nominator was good.","id":"switchblame_mistfitsreleased"}],"customBoxes":[{"title":"In the almanac JSON","content":"**Other nights:** If the Revenant died tonight: show the character tokens of their living non-traveller Neighbours."}],"firstNight":0,"otherNight":72.2718,"setup":false,"otherNightReminder":"If the Revenant died tonight: point your finger horizontally clockwise, and show the character token of the closest living player in that direction, then repeat that action for anti-clockwise.","art":"art/revenant-scp-fragmented-veil.png","jsonId":"revenant_scp_fragmented_veil","curata":false}','scp-fragmented-veil/revenant','published',datetime('now'),datetime('now')),
('navigator-scp-fragmented-veil','Navigator','townsfolk','legitch',NULL,'','SCP Fragmented Veil','{"slug":"navigator-scp-fragmented-veil","name":"Navigator","team":"townsfolk","ability":"Each night, choose a player (not yourself): you learn if they are a Minion. Characters marked on the script give reversed info.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Navigator (SCP-2799) is a device created by the SCP Foundation to track and learn about uncontained SCP anomalies.","summaryBullets":["Each night, the Navigator chooses a player and learns if they are a Minion.","On the script, there can be any amount of characters that marked with the Navigator''s character icon to indicate they will give reversed information to the Navigator.","This reversed information is normally false, but can be made true if an effect is being applied that makes the info they normally gain false.","It doesn''t matter if these characters lose their abilities by drunkenness, poisoning, or death, or if they gain abilities of a character that are marked - it only matters that the player themselves are a marked character or not.","The Navigator is not limited to choosing living players only."],"howToRun":["On the script, place a mark on characters you want to give reversed info for to the Navigator.","During each night, wake the Navigator. They point to a player. If the player is a Minion or a non-Minion marked on the script, nod your head yes. Otherwise, shake your head no. Put the Navigator to sleep."],"tips":["It''s recommended that you mark Townsfolk with a goal to bait being attacked at night, or Outsiders that don''t want to die or be found out by evil players {{i|(ex. Soldier, Ravenkeeper, Sage, Choirboy, Plague Doctor, Sweetheart, Hatter, Damsel.)}} to balance out the Navigator''s ability.","In scripts designed for smaller games, such as Teensyville, it''s better to reduce the marks to only Outsiders that fit the profile described."],"quote":"Woah, look at that baby spin. It''s... spinning really fast... ... Do you think it''s going to expl-","iconBy":"le_nuberto","customBoxes":[{"title":"Alternative JSON","content":"For if you don''t plan on using the character marking mechanic for the Navigator, despite being ill-advised, use this JSON.\n\n**Navigator █-** (Townsfolk)\nEach night, choose a player (not yourself): you learn if they are an Outsider or Minion. [+0 or +1 Outsider]\n\n**First night:** The Navigator points to a player; give the head signal (nod yes, shake no) for whether that player is a Minion or not.\n**Other nights:** The Navigator points to a player; give the head signal (nod yes, shake no) for whether that player is a Minion or not.\n**Setup:** yes\n**Credit:** Ability: @legitch. Image: @le_nuberto"}],"firstNight":62.2799,"otherNight":82.2799,"setup":true,"firstNightReminder":"The Navigator points to a player; give the head signal (nod yes, shake no) for whether that player is a Minion or not.","otherNightReminder":"The Navigator points to a player; give the head signal (nod yes, shake no) for whether that player is a Minion or not.","art":"art/navigator-scp-fragmented-veil.png","jsonId":"navigator_scp_fragmented_veil","curata":false}','scp-fragmented-veil/navigator','published',datetime('now'),datetime('now')),
('trilene','Trilḗnē','townsfolk','legitch, jessychu',NULL,'','SCP Fragmented Veil','{"slug":"trilene","name":"Trilḗnē","team":"townsfolk","ability":"If you die at night, choose 2 players: your chosen killer dies, even if for some reason they could not.","creator":"legitch, jessychu","appearsIn":"SCP Fragmented Veil","lede":"The Trilḗnē is the truth beyond death, the end of life''s story, the get-petty-revenge-on-your-killer solution.","summaryBullets":["Once the Trilḗnē meets death, they have a chance to guess who their killer is. If correct, they get annihilated to death.","This annihilation transcends protection and \"cannot die\" effects, leaving the sapless victim to always be vulnerable to a horrible smite.","There can only be 1 killer per this interaction. If there 2 or more players who would''ve killed the Trilḗnē, only the player that killed first is the killer to this ability.","It is possible for the Trilḗnē to kill the Demon - why not?"],"howToRun":["If the Trilḗnē died tonight, wake them. They point at 2 players. If the Trilḗnē chose their killer, that player dies - mark them with the **DEAD** reminder. This cannot be prevented in any way {{i|(except if the Trilḗnē doesn’t have their ability, such as if they’re drunk or poisoned)}}. Put the Trilḗnē to sleep."],"tips":["Typically, ''If/when you die at night'' characters will have jinxes with Demons that do not cause conventional night deaths to win the game to make them compatible together. By intention, some of these Demons have unconventional to no jinxes with the Trilḗnē in these cases. If not, just don''t use it in those scripts - the shoe doesn''t fit."],"quote":"*RING-RING* Hello, operator? I think my... I- your... yourrr refrid- reg- refrigd-... err... Uh... I... Uhhhmmmmmmm... ... ...Is your oven running?","iconBy":"le_nuberto","jinxes":[{"name":"Legion","align":"evil","text":"If only evil Legion voted to execute the Trilḗnē & they would''ve been, good wins.","id":"legion"},{"name":"Leviathan","align":"evil","text":"If the Leviathan nominates & executes the Trilḗnē, good wins.","id":"leviathan"},{"name":"Lil'' Monsta","align":"evil","text":"The Lil'' Monsta''s babysitter chooses a player each night to suggest the Storyteller killing. Trilḗnē is killed by the Lil'' Monsta if & only if they are chosen.","id":"lilmonsta"},{"name":"Ojo","align":"evil","text":"The Ojo chooses a player each night to suggest the Storyteller killing. The Trilḗnē is killed by the Ojo if & only if they are chosen.","id":"ojo"},{"name":"Yaggababble","align":"evil","text":"The Yaggababble chooses a player each night to suggest the Storyteller killing. The Trilḗnē is killed by the Yaggababble if & only if they are chosen.","id":"yaggababble"},{"name":"Axt","align":"evil","text":"If the Trilḗnē would be executed through the Axt''s ability, the Axt is instead.","id":"axt_hblreleased"},{"name":"Flabberghast","align":"evil","text":"The Flabberghast chooses a player(s) each night to suggest the Storyteller killing. The Trilḗnē is killed by the Flabberghast''s secondary ability if & only if they are chosen.","id":"flabberghast_hblreleased"}],"firstNight":0,"otherNight":55.2922,"reminders":["Dead"],"setup":false,"otherNightReminder":"If the Trilḗnē died tonight: the Trilḗnē points to a player. That player dies if they was the killer.","art":"art/trilene.png","jsonId":"triln_scp_fragmented_veil","curata":false}','scp-fragmented-veil/trilene','published',datetime('now'),datetime('now')),
('provenance','Provenance','townsfolk','legitch',NULL,'','SCP Fragmented Veil','{"slug":"provenance","name":"Provenance","team":"townsfolk","ability":"You start knowing that 1 of 3 players is a Townsfolk. If they would die, they don''t, then you''re drunk.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Provenance (SCP-3668) is an ancient shield that summons the dead to defend their descendants from all harm against them.","summaryBullets":["During the first night, the Provenance is woken, shown three players, at-least one of which is a Townsfolk.","They learn this only once and then learn nothing more.","The first time that player would die for any reason, they remain alive. They don’t learn that this ability saved their life.","The Provenance can learn multiple Townsfolk, but only one of them will be protected.","If another character’s ability protects that player from death, the Provenance does not use their ability. Only the time that the Provenance''s target would actually for realsy bona fide be dead does their ability trigger."],"howToRun":["While preparing the first night, put the Provenance''s **TOWNSFOLK** reminder token by any Townsfolk character token, and put the Provenance''s two **WRONG** reminder token by any other character token.","During the first night, wake the Provenance and point to the three players marked **TOWNSFOLK** and **WRONG**. Put the Provenance to sleep. Remove the Provenance''s **WRONG** reminder tokens when convenient.","If the player marked with the **TOWNSFOLK** reminder token would die, they remain alive, but they die if the Provenance is drunk or poisoned. If that player was executed, declare that the player was executed but remains alive {{i|(do not say why)}}.","Either way, the Provenance becomes drunk - mark them with the **DRUNK** reminder token."],"quote":"I will protect for as long as you my kin. My spawn. My flame. Is that not what bonds and family are about? Is that not what life is about? Cherish everyday like it is a gift. Cherish everyday because it is my gift. You are safe here. You are safe now. Goodnight.","iconBy":"le_nuberto","customBoxes":[{"title":"Alternative JSON & How to Run (Older)","content":"For if you feel like the Provenance should be more generic in which good players they can protect, use this JSON.\n\nWhile preparing the first night, put the Provenance''s **GOOD** reminder token by any good player''s token, and put the Provenance''s **WRONG** reminder token by any other character token.\n\nDuring the first night, wake the Provenance and point to the players marked **GOOD** and **WRONG**. Put the Provenance to sleep. Remove the Provenance''s **WRONG** reminder token when convenient.\n\nIf the player marked with the **GOOD** reminder token would die, they remain alive, but they die if the Provenance is drunk or poisoned. If that player was executed, declare that the player was executed but remains alive {{i|(do not say why)}}.\n\nEither way, the Provenance becomes drunk - mark them with the **DRUNK** reminder token.\n\n**Provenance █** (Townsfolk)\nYou start knowing that 1 of 2 players is good. If they would die, they don''t, then you''re drunk.\n\n**First night:** Point to two players, one of which is good.\n**Reminders:** Good, Wrong, Drunk\n**Credit:** Ability: @legitch. Image: @le_nuberto"}],"firstNight":53.3668,"otherNight":0,"reminders":["Townsfolk","Wrong","Wrong","Drunk"],"setup":false,"firstNightReminder":"Point to three players, one of which is a Townsfolk.","art":"art/provenance.png","jsonId":"provenance_scp_fragmented_veil","curata":false}','scp-fragmented-veil/provenance','published',datetime('now'),datetime('now')),
('skynet-agent','Skynet Agent','townsfolk','legitch',NULL,'','SCP Fragmented Veil','{"slug":"skynet-agent","name":"Skynet Agent","team":"townsfolk","ability":"Each night*, choose a living player: if the Minion marked on the script is chosen, they lose their ability & die. [That marked minion is in-play]","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Skynet Agent has a specific Minion in their sights, and will hunt them down to the ends of the earth.","summaryBullets":["The Minion can be in play without the Skynet Agent. During the setup phase, if the Skynet Agent is in play and the Minion marked on the script isn''t, they instead replace another Minion. If that Minion is already in play, the Skynet Agent doesn''t add a duplicate.","If the Skynet Agent correctly chooses the marked Minion at night, they are drunk and they die.","The Skynet Agent''s ability will only concern the one Minion marked on the script, regardless if they are dead or alive - if the marked Minion does die by any other circumstances, another Minion won''t be marked."],"howToRun":["On the script, place a mark on the Minion you want to be the target of the Skynet Agent they want to hunt down.","Each night except the first, wake the Skynet Agent. They point at any player. If they choose the Minion marked on the script, that player {{i|dies and loses their ability}} - mark them with the **ELIMINATED** reminder. Put the Skynet Agent to sleep."],"quote":"Y''know, I am quite content being a Silver Bullet hunter. It''s not like its every once in a while you get to bag a Werewolf on a Christmas morning.","iconBy":"le_nuberto","jinxes":[{"name":"Matsuraid","align":"evil","text":"The Matsuraid registers as a Minion to the Skynet Agent if marked on the script.","id":"matsuraid_hblreleased"}],"firstNight":0,"otherNight":54.5343,"reminders":["Eliminated"],"setup":true,"otherNightReminder":"The Skynet Agent points to a player. If they point to the Minion marked on the script, that player dies.","art":"art/skynet-agent.png","jsonId":"skynetagent_scp_fragmented_veil","curata":false}','scp-fragmented-veil/skynet-agent','published',datetime('now'),datetime('now')),
('hammer-down','Hammer Down','townsfolk','legitch',NULL,'','SCP Fragmented Veil','{"slug":"hammer-down","name":"Hammer Down","team":"townsfolk","ability":"On your 1st day, state your conditions. Whilst true, if a teammate was to die during the day, they don''t & you''re drunk.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Hammer Down is the **[REDACTED]** **[REDACTED]** ...tactical unit... **[REDACTED]** ...rescue operation... **[REDACTED]** **[REDACTED]** **[REDACTED]** ... last resort.","summaryBullets":["The Hammer Down tactically selects when they protect a teammate, or perhaps who they protect.","This does not regard by default the character type of who they protect, only that they are on the same alignment.","If the Hammer Down has not set down any conditions before the end of the 1st day, no one will be protected by them.","The Hammer Down protects against any death during the day, not just executions","These conditions do not have to be specific to the player that is dieing, they may relate to anything provided it is definite and non-subjective.","This can include use of ''and'' rules, ''or'' rules, and ''exclusive-or/xor'' rules.","Being drunk or poisoned does not inhibit how the Hammer Down can set their conditions."],"howToRun":["During the first day, the Hammer Down may add any new conditions, or remove any conditions they previously set today, either publicly or by having a private discussion with you. Write the current set of conditions on a piece of paper. If prompted, show them what their current conditions are to remind them or clarify any confusion. That dusk, mark the Hammer Down with the **PAST DAY 1** reminder token to indicate that have used their first day.","During the day, if the Hammer Down''s conditions are true, and a player of the same alignment as them would die, they remain alive {{i|(do not say why.)}} The Hammer Down becomes drunk - mark them with the **DRUNK** reminder token."],"tips":["**Optional rule:** If the Hammer Down has not set down their conditions on the 1st day, their conditions will automatically be set to ''always/true''."],"quote":"62 alarms. All teams respond, code 3. All units BOL for 243 suspect. All units return to code 12. 243 assault on Protection Team. 10-0, begin scanning.","iconBy":"le_nuberto","customBoxes":[{"title":"Credit","content":"Ability: @legitch & **[REDACTED AT REQUEST]**. Image: @le_nuberto"},{"title":"Alternative JSON & How to Run (Older)","content":"For if you want the Hammer Down to only protect against executions instead of all deaths during the day, use this JSON. It may be better depending on the script it is placed on.\n\nDuring the first day, the Hammer Down may add any new conditions, or remove any conditions they previously set today, either publicly or by having a private discussion with you. Write the current set of conditions on a piece of paper. If prompted, show them what their current conditions are to remind them or clarify any confusion. That dusk, mark the Hammer Down with the **PAST DAY 1** reminder token to indicate that have used their first day.\n\nDuring the day, if the Hammer Down''s conditions are true, and a player of the same alignment as them would die by execution, they remain alive {{i|(do not say why.)}} The Hammer Down becomes drunk - mark them with the **DRUNK** reminder token.\n\n**Hammer Down █** (Townsfolk)\nOn your 1st day, state your conditions. Whilst true, if a teammate was to die by execution, they don''t & you''re drunk.\n\n**Reminders:** Past Day 1, Drunk\n**Credit:** Ability: @legitch & [REDACTED AT REQUEST]. Image: @le_nuberto\n\n**Jinxes:**\nAbysewhell: Players who die by an evil player answering their question correctly register as executed to the Hammer Down."}],"firstNight":0,"otherNight":0,"reminders":["Past Day 1","Drunk"],"setup":false,"art":"art/hammer-down.png","jsonId":"hammerdown_scp_fragmented_veil","curata":false}','scp-fragmented-veil/hammer-down','published',datetime('now'),datetime('now'));
